import defineClasses from '../util/defineClasses'

function definePadding(padding) {
  return _.flatMap(padding, (size, modifier) => {
    return defineClasses({
      [`pt-${modifier}`]: {
        'padding-top': `${size}`,
      },
      [`pr-${modifier}`]: {
        'padding-right': `${size}`,
      },
      [`pb-${modifier}`]: {
        'padding-bottom': `${size}`,
