        'padding-left': `${size}`,
      },
      [`px-${modifier}`]: {
        'padding-left': `${size}`,
        'padding-right': `${size}`,
      },
      [`py-${modifier}`]: {
        'padding-top': `${size}`,
        'padding-bottom': `${size}`,
      },
      [`p-${modifier}`]: {
        padding: `${size}`,
      },
    })
  })
}

function defineMargin(margin) {
  return _.flatMap(margin, (size, modifier) => {
    return defineClasses({
      [`mt-${modifier}`]: {
        'margin-top': `${size}`,
      },
      [`mr-${modifier}`]: {
        'margin-right': `${size}`,
      },
      [`mb-${modifier}`]: {
