      },
      [`mx-${modifier}`]: {
        'margin-left': `${size}`,
        'margin-right': `${size}`,
      },
      [`my-${modifier}`]: {
        'margin-top': `${size}`,
        'margin-bottom': `${size}`,
      },
      [`m-${modifier}`]: {
        margin: `${size}`,
      },
    })
  })
}

function defineNegativeMargin(negativeMargin) {
  return _.flatMap(negativeMargin, (size, modifier) => {
    size = `${size}` === '0' ? `${size}` : `-${size}`

    return defineClasses({
      [`-mt-${modifier}`]: {
        'margin-top': `${size}`,
      },
      [`-mr-${modifier}`]: {
        'margin-right': `${size}`,
      },
      [`-mb-${modifier}`]: {
        'margin-bottom': `${size}`,
